from fastapi import BackgroundTasks, FastAPI
from pydantic import BaseModel

from app.mail import send_welcome_email
from app.users import create_user

app = FastAPI()


class SignupIn(BaseModel):
    email: str
    name: str


@app.post("/signup", status_code=201)
def signup(body: SignupIn, background_tasks: BackgroundTasks):
    user_id = create_user(body.email, body.name)
    background_tasks.add_task(send_welcome_email(body.email, body.name))
    return {"id": user_id}
